const arena=document.querySelector('#arena'),ex=document.querySelector('#exercise'),result=document.querySelector('#result');let timer,run=0,guide=localStorage.getItem('astra-guide')||'Nova';
function clear(){clearTimeout(timer);run++;ex.innerHTML='';result.textContent=''}
document.querySelectorAll('[data-launch]').forEach(b=>b.onclick=()=>{clear();document.querySelector('#modal-title').textContent=`Your mission awaits, ${guide}.`;arena.showModal()});
document.querySelector('.close').onclick=()=>{clear();arena.close()};arena.addEventListener('close',clear);
function mode(m){clear();if(!arena.open)arena.showModal();document.querySelector('#modal-title').textContent=m==='focus'?'Find your focus.':'Find your rhythm.';document.querySelector('#modal-desc').textContent=m==='focus'?'Tap when the panel turns green. Complete three rounds.':'A gentle 30-second shadowboxing round. Keep space around you and move at your own pace.';if(m==='focus'){let rounds=[];function round(){const token=run;ex.innerHTML='<button class="target" style="background:#77503c;color:white">Wait for green…</button>';let ready=false,start;const b=ex.firstChild;b.onclick=()=>{if(!ready){clearTimeout(timer);result.textContent='A little early. Try again.';round();return}rounds.push(Math.round(performance.now()-start));result.textContent=`Round ${rounds.length}: ${rounds.at(-1)} ms`;if(rounds.length<3)timer=setTimeout(round,650);else{ex.innerHTML='<button>Play again</button>';ex.firstChild.onclick=()=>mode('focus');result.textContent=`Average reaction: ${Math.round(rounds.reduce((a,b)=>a+b)/3)} ms. Mission complete!`}};timer=setTimeout(()=>{if(token!==run)return;ready=true;start=performance.now();b.textContent='TAP NOW ✦';b.style.background='#d4f879';b.style.color='#14200a'},1400+Math.random()*2300)}round()}else{ex.innerHTML='<button>Begin 30-second round</button>';ex.firstChild.onclick=()=>{let t=30;const tick=()=>{ex.innerHTML=`<h2>${t}s</h2><p>${['Jab · Cross','Guard · Breathe','Step · Jab','Cross · Reset'][Math.floor((30-t)/5)%4]}</p>`;if(t-- >0)timer=setTimeout(tick,1000);else{result.textContent='Round complete. Breathe, reset, and celebrate showing up.';ex.innerHTML='<button>Train again</button>';ex.firstChild.onclick=()=>mode('boxing')}};tick()}}}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>mode(b.dataset.mode));
