if(!crew){const holder=document.querySelector('#crew .section-top');const grid=document.createElement('div');grid.className='crew-grid';const old=document.querySelector('#crew .crew-grid');}
document.querySelectorAll('#crew .portrait').forEach(el=>{el.parentElement.onclick=()=>{}});
const cards=document.querySelector('#crew .crew-grid');
function choose(name){guide=name;localStorage.setItem('astra-guide',name);document.querySelector('#guide-note').textContent=`${name} is ready. Let's discover what you're capable of.`;document.querySelectorAll('#crew button').forEach(b=>b.textContent=b.dataset.guide===name?'SELECTED · '+name.toUpperCase():'CHOOSE '+b.dataset.guide.toUpperCase())}
document.querySelectorAll('#crew button').forEach((b,i)=>{b.dataset.guide=['Nova','Rex','Echo'][i];b.onclick=()=>choose(b.dataset.guide)});choose(guide);
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.remove('pending');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>{e.classList.add('pending');observer.observe(e)});document.querySelector('#motion').onclick=e=>{document.body.classList.toggle('still');e.target.textContent='Motion: '+(document.body.classList.contains('still')?'off':'on')};
function choose(name){guide=name;localStorage.setItem('astra-guide',name);document.querySelector('#guide-note').textContent=`${name} is ready. Let's discover what you're capable of.`;document.querySelectorAll('[data-char]').forEach(b=>{b.classList.toggle('selected',b.dataset.char===name);b.querySelector('span').textContent=b.dataset.char===name?'YOUR GUIDE':'CHOOSE '+b.dataset.char.toUpperCase()})}
// Restore character card content before binding selection.
const names=['Nova','Rex','Echo'],roles=['THE EXPLORER','THE FIGHTER','THE STRATEGIST'],symbols=['✦','拳','◈'],lines=['Curiosity is your superpower.','Turn persistence into power.','Find clarity in the chaos.'];
document.querySelectorAll('[data-char]').forEach((b,i)=>{b.innerHTML=`<div class="portrait ${names[i].toLowerCase()}">${symbols[i]}</div><small>${roles[i]}</small><h3>${names[i]}</h3><p>${lines[i]}</p><span>CHOOSE ${names[i]}</span>`;b.onclick=()=>choose(names[i])});choose(guide);
function mode(type){clear();if(!arena.open)arena.showModal();document.querySelector('#modal-title').textContent=type==='boxing'?'Find your rhythm.':'Focus. Wait. React.';document.querySelector('#modal-desc').textContent=type==='boxing'?'A gentle shadowboxing demo. Give yourself space and move at your own pace.':'Tap only when the target turns lime. Try three rounds.';if(type==='boxing'){ex.innerHTML='<button id="begin">Begin 30-second round</button>';document.querySelector('#begin').onclick=()=>{const cues=['JAB','CROSS','GUARD','JAB · CROSS','SLIP','RESET'];let n=0,secs=30;const tick=()=>{ex.innerHTML=`<h2 style="color:var(--lime);margin:25px 0">${cues[n++%cues.length]}</h2><p>${secs}s remaining · Breathe and keep your guard relaxed.</p>`;secs-=3;if(secs>=0)timer=setTimeout(tick,3000);else{ex.innerHTML='<button id="again">Round complete · Go again</button>';result.textContent='Mission complete. Take a breath and reset.';document.querySelector('#again').onclick=()=>mode('boxing')}};tick()}}else{let count=0,scores=[];function round(){ex.innerHTML='<button class="target" style="background:#46533b;color:white">Wait for lime…</button>';const target=ex.firstChild;let ready=false,start;target.onclick=()=>{if(!ready){clearTimeout(timer);result.textContent='A little early. Try again.';round();return}scores.push(Math.round(performance.now()-start));count++;result.textContent=`Round ${count}: ${scores.at(-1)} ms`;if(count<3)round();else{ex.innerHTML='<button>Play again</button>';ex.firstChild.onclick=()=>mode('focus');result.textContent=`Mission complete · Average: ${Math.round(scores.reduce((a,b)=>a+b)/3)} ms`}};timer=setTimeout(()=>{ready=true;start=performance.now();target.style.background='var(--lime)';target.style.color='#172018';target.textContent='TAP NOW ✦'},1500+Math.random()*2000)}round()}}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>mode(b.dataset.mode));
